import base64
import sys

# Constants for OoT Save Context (from typical OoTMM/OoT offsets)
OotOffUpgrades = 0xA0
OotOffPerm = 0xD4
OotPermEntrySize = 0x1C
OotPermExtraOff = 0x8

# Data from JSON
data_base64 = ""
data = base64.b64decode(data_base64)

# Upgrades
upgrades = int.from_bytes(data[OotOffUpgrades:OotOffUpgrades+4], "big")
wallet_bits = (upgrades >> 16) & 0x3
print(f"OotOffUpgrades (0x{OotOffUpgrades:X}): 0x{upgrades:08X}")
print(f"  Wallet Bits (>>16 & 0x3): {wallet_bits}")

# Extra Records
# extra record 2 OotOffPerm + 2*OotPermEntrySize + OotPermExtraOff
off2 = OotOffPerm + 2 * OotPermEntrySize + OotPermExtraOff
record2 = data[off2]
print(f"Extra Record 2 (at 0x{off2:X}): 0x{record2:02X}")

# Extra Records 7 and 13
off7 = OotOffPerm + 7 * OotPermEntrySize + OotPermExtraOff
record7 = data[off7]
print(f"Extra Record 7 (at 0x{off7:X}): 0x{record7:02X}")

off13 = OotOffPerm + 13 * OotPermEntrySize + OotPermExtraOff
record13 = data[off13]
print(f"Extra Record 13 (at 0x{off13:X}): 0x{record13:02X}")
